            JSONObject facts=new JSONObject().put("character",persona.optString("name")).put("latestUserText",user).put("latestUserTime",MessageTime.label(p.lastAt,ScheduleData.zone(start).getId())).put("history",recent).put("existingMemories",candidates);if(promises)facts.put("activePromises",PromiseData.context(start,p.character)).put("promiseChecks",promiseChecks);
