            JSONObject data=store.personal();PersonalData.refresh(data,PersonalData.today());Progression.upgrade(data);JSONObject applied=null;if(judge&&analysis.optJSONObject("judged")!=null)applied=Progression.apply(data,p.character,p.session,analysis.getJSONObject("judged"),p.lastAt);
