            JSONObject effects=new JSONObject().put("life",lifeAnswer.effects).put("personal",data).put("base",start).put("notebookEpoch",notebookEpoch).put("timeEvents",remember&&prefs.getBoolean("timelineAuto",false)?MemoryNotebook.proposals(analysis.optJSONArray("timeEvents"),MemoryNotebook.range(store,p.session,p.firstUserId,p.lastUserId),p.character,p.session):new JSONArray()).put("events",events).put("name",persona.optString("name")).put("warning",warning).put("heartScene",scene).put("appealExplanation",appealExplanation);if(applied!=null)effects.put("chatJudgment",new JSONObject().put("warmth",Math.max(0,applied.optDouble("delta"))).put("hurt",Math.max(0,-applied.optDouble("delta"))).put("out",analysis.getJSONObject("judged").optBoolean("out_of_line")));if(remember&&prefs.getBoolean("hibiDiary",false))effects.put("diaryMoment",DiaryData.moment(analysis,user,p.lastAt,start));ChatStore.PendingReply fresh=store.pending(p.id);if(fresh==null||fresh.revision!=p.revision||!fresh.status.equals("generating"))return;
