    static boolean requeueOrphan(ChatStore store,ChatStore.PendingReply row){synchronized(CALL_LOCK){if(OWNERS.containsKey(key(row.id,row.revision)))return false;store.requeueInterrupted(row.id,row.revision,System.currentTimeMillis());return true;}}
    static boolean owned(String id,long revision,Thread owner){synchronized(CALL_LOCK){return owner!=null&&OWNERS.get(key(id,revision))==owner;}}
    private static boolean isStopped(String id,long revision){synchronized(CALL_LOCK){return STOPPED.contains(key(id,revision));}}
    private static JSONObject findCharacter(Context c,String who)throws Exception{JSONArray rows=readArray(c,"characters.json");for(int i=0;i<rows.length();i++)if(who.equals(rows.getJSONObject(i).getString("id")))return rows.getJSONObject(i);throw new IOException("角色资料已不存在");}
    private static JSONArray readArray(Context c,String name)throws Exception{return new JSONArray(readText(c,name,4*1024*1024));}
    private static String readText(Context c,String name,int max)throws Exception{try(InputStream in=c.getAssets().open(name)){return new String(StoryFiles.read(in,max),"UTF-8");}}
    private static String judgeProvider(android.content.SharedPreferences p){String provider=p.getString("judgeProvider","compatible"),url=p.getString("judgeUrl","").trim(),model=p.getString("judgeModel","").trim();if(provider.equals("compatible")&&model.startsWith("decision-model")&&url.matches("https://[A-Za-z0-9-]+\\.(cn-beijing|ap-southeast-1)\\.maas\\.aliyuncs\\.com/compatible-mode/v1/?"))return "bailian";return provider;}
    private static String[] service(Context c,android.content.SharedPreferences p,String role,String chatUrl,String chatKey,String chatModel)throws Exception{String url=p.getString(role+"Url","").trim(),model=p.getString(role+"Model",role.equals("background")?p.getString("analysisModel",""):"").trim(),key=Vault.read(c,role+"Key");if(url.isEmpty()){url=chatUrl;if(key.isEmpty())key=chatKey;}else if(key.isEmpty())throw new IOException("请填写独立模型密钥");return new String[]{url,key,model.isEmpty()?chatModel:model};}
    private ReplyFallback(){}
